[Tool: Read → 1: //! Single-pred-single-succ block merging.
2: //!
3: //! Pre-structuring pass that collapses linear chains of basic blocks into a
4: //! single block. A block `B` is merged into its predecessor `A` when:
5: //!
6: //!   1. `B` has exactly one predecessor in the real (non-synthetic) CFG, namely `A`.
7: //!   2. `A` has exactly one real successor, namely `B`.
8: //!   3. `A` is not its own successor (no self-loop).
9: //!   4. `B` is not the function entry block.
10: //!   5. `A` is not in `B`'s successor list (would create a spurious self-loop
11: //!      after merging — typical of back-edges from `B` to `A`).
12: //!   6. `A`'s last instruction is not a control-flow terminator other than
13: //!      `BRANCH` (an unconditional jump). Specifically, `CBRANCH`, `BRANCHIND`,
14: //!      `RETURN`, and call-with-fallthrough cases are NOT merged because
15: //!      their semantics rely on `A` ending with a terminator.
16: //!
17: //! When these conditions hold, `B`'s instructions are appended to `A` after
18: //! stripping `A`'s trailing `BRANCH` (if any) and `B` is removed from the
19: //! function. Successors of `A` are replaced with successors of `B`. Any other
20: //! block that listed `B` as a successor is rewritten to point to `A`
21: //! (this only happens via `B`'s successor entries, which we never see — the
22: //! single-predecessor invariant guarantees no other block references `B`).
23: //!
24: //! The pass iterates to a fixed point. Each iteration is `O(blocks * edges)`;
25: //! the fixed point is reached in at most `O(blocks)` iterations.
26: 
27: use std::collections::{BTreeMap, BTreeSet};
28: 
29: use unlace_ir::{BasicBlock, BlockId, Function, IrOp};
30: 
31: /// Run block-merging to a fixed point on `func`, returning the number of
32: /// merges performed across all iterations.
33: pub fn merge_linear_blocks(func: &mut Function) -> usize {
34:     let max_iters = func.blocks.len().saturating_mul(2).max(64);
35:     let func_name = func.name.clone();
36:     let mut total = 0;
37:     let mut iter = 0;
38:     loop {
39:         iter += 1;
40:         if iter > max_iters {
41:             tracing::error!(
42:                 func = %func_name,
43:                 blocks = func.blocks.len(),
44:                 max_iters,
45:                 "merge_linear_blocks did not converge"
46:             );
47:             panic!("merge_linear_blocks did not converge on '{func_name}' after {max_iters} iters",);
48:         }
49:         let merges = merge_one_pass(func);
50:         if merges > 0 {
51:             tracing::trace!(
52:                 func = %func_name,
53:                 iter,
54:                 merges,
55:                 blocks = func.blocks.len(),
56:                 "merge_linear_blocks iter"
57:             );
58:         }
59:         if merges == 0 {
60:             return total;
61:         }
62:         total += merges;
63:     }
64: }
65: 
66: /// One pass of block merging. Returns the number of merges performed.
67: fn merge_one_pass(func: &mut Function) -> usize {
68:     let preds = compute_predecessors(func);
69:     let entry = func.entry;
70: 
71:     let candidates: Vec<(BlockId, BlockId)> = func
72:         .blocks
73:         .iter()
74:         .filter_map(|(&a_id, a_block)| {
75:             let succ = single_real_successor(a_block)?;
76:             if succ == a_id {
77:                 return None;
78:             }
79:             if succ == entry {
80:                 return None;
81:             }
82:             let succ_preds = preds.get(&succ)?;
83:             if succ_preds.len() != 1 || !succ_preds.contains(&a_id) {
84:                 return None;
85:             }
86:             let b_block = func.blocks.get(&succ)?;
87:             if b_block.successors.contains(&a_id) {
88:                 return None;
89:             }
90:             if !is_mergeable_terminator(a_block) {
91:                 return None;
92:             }
93:             Some((a_id, succ))
94:         })
95:         .collect();
96: 
97:     let mut merged_into: BTreeSet<BlockId> = BTreeSet::new();
98:     let mut count = 0;
99: 
100:     for (a_id, b_id) in candidates {
101:         if merged_into.contains(&a_id) || merged_into.contains(&b_id) {
102:             continue;
103:         }
104:         if perform_merge(func, a_id, b_id) {
105:             merged_into.insert(a_id);
106:             merged_into.insert(b_id);
107:             count += 1;
108:         }
109:     }
110: 
111:     count
112: }
113: 
114: /// Append `B`'s instructions onto `A`, replacing `A`'s successors with `B`'s,
115: /// and remove `B` from the function. Returns `true` on success.
116: fn perform_merge(func: &mut Function, a_id: BlockId, b_id: BlockId) -> bool {
117:     let Some(b_block) = func.blocks.remove(&b_id) else {
118:         return false;
119:     };
120: 
121:     let Some(a_block) = func.blocks.get_mut(&a_id) else {
122:         func.blocks.insert(b_id, b_block);
123:         return false;
124:     };
125: 
126:     if matches!(a_block.insns.last().map(|i| i.op), Some(IrOp::Branch)) {
127:         a_block.insns.pop();
128:     }
129: 
130:     a_block.insns.extend(b_block.insns);
131:     a_block.successors = b_block.successors;
132:     true
133: }
134: 
135: /// If `block` has exactly one successor in its `successors` list AND its last
136: /// instruction is a `BRANCH` (or it has no terminator and falls through),
137: /// return that successor. Otherwise return `None`.
138: fn single_real_successor(block: &BasicBlock) -> Option<BlockId> {
139:     if block.successors.len() != 1 {
140:         return None;
141:     }
142:     Some(block.successors[0])
143: }
144: 
145: /// A predecessor's terminator must be either `BRANCH` (unconditional) or a
146: /// non-terminator (fallthrough) for merging to be sound. `CBRANCH` /
147: /// `BRANCHIND` / `RETURN` rely on the terminator marking the end of `A`'s
148: /// statements.
149: fn is_mergeable_terminator(block: &BasicBlock) -> bool {
150:     match block.insns.last().map(|i| i.op) {
151:         None => true,
152:         Some(IrOp::Branch) => true,
153:         Some(IrOp::Cbranch | IrOp::Branchind | IrOp::Return | IrOp::Call | IrOp::Callind) => false,
154:         Some(_) => true,
155:     }
156: }
157: 
158: /// Compute the predecessor map by scanning every block's `successors` list.
159: fn compute_predecessors(func: &Function) -> BTreeMap<BlockId, Vec<BlockId>> {
160:     let mut preds: BTreeMap<BlockId, Vec<BlockId>> = BTreeMap::new();
161:     for (&src, block) in &func.blocks {
162:         for &dst in &block.successors {
163:             preds.entry(dst).or_default().push(src);
164:         }
165:     }
166:     for v in preds.values_mut() {
167:         v.sort();
168:         v.dedup();
169:     }
170:     preds
171: }
